import { Component, Element, Host, Prop, h } from "@stencil/core";
import retargetEvents from "react-shadow-dom-retarget-events";
import { renderChart } from "./RenderChart";

/**
 * @since 0.0.6
 * @status beta
 *
 */

@Component({
	tag: "hbr-sparkline",
	styleUrl: "sparkline.scss",
	shadow: true,
})
export class HbrSparkline {
	/**
	 * config object for the chart. Please review https://nivo.rocks/line/ for more detail.
	 */
	@Prop() config: any = { data: [] };
	/**
	 * width of the container in CSS length units
	 */
	@Prop() width = "100%";
	/**
	 * height of the container in CSS length units
	 */
	@Prop() height = "360px";

	@Element() private el: HTMLHbrSparklineElement;

	componentDidLoad() {
		this.createChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		this.createChart();
		return false;
	}

	createChart() {
		const root = this.el.shadowRoot.querySelector("div");

		renderChart({
			el: root,
			config: { ...this.config },
		});
	}

	render() {
		return (
			<Host>
				<div id="root" style={{ width: this.width, height: this.height }} />
			</Host>
		);
	}
}
