import { ResponsiveLine as Line } from "@harbor-charts/line";
//@ts-ignore
import { area } from "d3-shape";
import merge from "deepmerge";
import React from "react";
import { createRoot } from "react-dom/client";
import { generateDataWithNulls, getBaseConfig } from "../../utils/charts";
import { combineMergeArray } from "../../utils/combineMergeArray";

function getSparklineBaseConfig(datasize, data) {
	return {
		margin: { top: 4, right: 4, bottom: 4, left: 4 },
		//padding: 0,
		xScale: { type: "point" },
		yScale: {
			type: "linear",
			min: "auto",
			max: "auto",
			stacked: false,
			reverse: false,
		},
		curve: "linear",
		enablePoints: true,
		pointLabelYOffset: -12,
		lineWidth: 2,
		pointSymbol: (props) => {
			const { size, color, borderWidth, borderColor, datum } = props;
			let gReact;
			if (
				datum.x === data[datasize - 1].x ||
				datum.pointSymbol ||
				datum.pointSymbolNull
			) {
				gReact = React.createElement(
					"g",
					{},

					React.createElement("circle", {
						r: size / (datum.pointSymbolNull ? 4 : 2),
						strokeWidth: borderWidth,
						stroke: borderColor,
						fill: color,
						fillOpacity: 1,
					}),
				);
			} else {
				gReact = React.createElement("g", {}, null);
			}

			return gReact;
		},
		colors: ["var(--hbr-sparkline-line1-color)", "transparent", "transparent"],
		theme: {
			grid: {
				line: {
					stroke: "var(--hbr-sparkline-grid-color)",
					strokeWidth: 1,
				},
			},
			axis: {
				ticks: {
					text: {
						fontSize: "var(--hbr-sparkline-tick-text-size)",
						fill: "var(--hbr-sparkline-tick-text-color)",
						lineHeight: "var(--hbr-sparkline-tick-line-height)",
						letterSpacing: "var(--hbr-sparkline-tick-letter-spacing)",
					},
				},
			},
		},
		axisTop: null,
		axisRight: null,
		enableGridX: false,
		enableGridY: true,

		axisBottom: {
			orient: "bottom",
			tickSize: 0,
			tickRotation: 0,
			legend: "",
			format: (value) => {
				if (value === data[0].x || value === data[datasize - 1].x) {
					return value;
				}
				return "";
			},
			tickPadding: 15,
		},
		//useMesh: true,
		//enableSlices: "x",

		axisLeft: null,
		/* layers: [
        'grid', 
        'markers', 
        'areas',
        'crosshair', 
        'lines', 
        'axes', 
        'points', 
        'slices', 
        'mesh', 
        'legends'
    ] */
	};
}

export function renderChart({ el, config }: any) {
	/**
	 * merges: common charts config < bar charts common config < config from user
	 * TODO: do we need un modifiable config?
	 */

	const dataSize = config.data?.[0] ? config.data[0].data.length : null;

	const data = config.data?.[0]?.data ? config.data[0].data : null;

	config.data = generateDataWithNulls(config.data);

	let finalConfig;
	//if (mergereplace && dataSize && data & config.data) {
	//  finalConfig = merge.all([getBaseConfig(), getSparklineBaseConfig(dataSize, data), config], customMerge);
	//} else if (dataSize && data && config.data) {
	finalConfig = merge.all(
		[getBaseConfig(), getSparklineBaseConfig(dataSize, data), config],
		{
			arrayMerge: combineMergeArray,
		},
	);
	//}

	const root = createRoot(el);
	/* @ts-ignore */
	root.render(React.createElement(Line, finalConfig, null));
}
